/**
 * A local photo in AVIF, WebP and JPEG (generated by `npm run images` into
 * public/images/<name>-<width>.<ext>). The browser downloads only the first
 * format it supports, at the width it needs.
 */
export default function Picture({ name, widths, width, height, alt, sizes = '100vw', className = '', loading = 'lazy', fetchPriority }) {
  const set = (ext) => widths.map((w) => `/images/${name}-${w}.${ext} ${w}w`).join(', ')
  const largest = widths[widths.length - 1]
  return (
    <picture>
      <source type="image/avif" srcSet={set('avif')} sizes={sizes} />
      <source type="image/webp" srcSet={set('webp')} sizes={sizes} />
      <img
        src={`/images/${name}-${largest}.jpg`}
        srcSet={set('jpg')}
        sizes={sizes}
        alt={alt}
        width={width}
        height={height}
        loading={loading}
        decoding="async"
        fetchpriority={fetchPriority}
        className={className}
      />
    </picture>
  )
}
